import { Component, HostListener, Input } from '@angular/core';

@Component({
    selector: 'app-datepicker',
    templateUrl: './datepicker.component.html',
    styleUrls: ['./datepicker.component.css']
})
export class DatepickerComponent {
    @Input() dateValue: Date = new Date();
    @Input() timeValueString: string = '00:00';
    dateValueString: string = this.formatDateToDDMMYYYY(this.dateValue);

    @Input() isReadOnly: boolean = false;
    @Input() labelString: string | undefined;
    @Input() showLabel: boolean = true;
    @Input() showOuterDiv: boolean = false;
    @Input() showTimePicker: boolean = false;

    showDatePicker: boolean = false;
    hasSelectedDate: boolean = false;

    monthsNames: string[] = [
        'January',
        'February',
        'March',
        'April',
        'May',
        'June',
        'July',
        'August',
        'September',
        'October',
        'November',
        'December'
    ];

    weekDaysNames: string[] = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    calendar: SingleDay[][] = [];
    currentMonth: number = this.dateValue.getMonth();
    currentYear: number = this.dateValue.getFullYear();

    ngOnInit() {
        if (this.labelString === undefined) {
            this.labelString =
                'Date' + (this.showTimePicker ? ' and Time' : '');
        }
        this.populateCalendar();
    }

    nextMonth() {
        this.currentMonth++;
        if (this.currentMonth > 11) {
            this.currentMonth = 0;
            this.currentYear++;
        }
        this.dateValue = new Date(this.currentYear, this.currentMonth, 1);
        this.populateCalendar();
    }
    prevMonth() {
        this.currentMonth--;
        if (this.currentMonth < 0) {
            this.currentMonth = 11;
            this.currentYear--;
        }
        this.dateValue = new Date(this.currentYear, this.currentMonth, 1);
        this.populateCalendar();
    }

    @HostListener('document:click', ['$event'])
    handleClick(event: Event): void {
        const datepickerElement = document.getElementsByClassName(
            'datepicker-wrapper'
        )[0] as HTMLElement;
        const targetElement = event.target as HTMLElement;

        // Check if the clicked element is not the datepicker or a descendant of the datepicker
        if (!datepickerElement.contains(targetElement)) {
            // The click was outside the datepicker, so hide it
            // datepickerElement.style.display = 'none';
            this.showDatePicker = false;
        }
    }

    dayClick(day: SingleDay) {
        if (day.currentMonth ) {
            this.prevMonth();
        }
        if (day.isNextMonth) {
            this.nextMonth();
        }

        this.dateValue = new Date(
            this.dateValue.getFullYear(),
            this.dateValue.getMonth(),
            day.value
        );
        this.dateValueString = this.formatDateToDDMMYYYY(this.dateValue);
        this.showDatePicker = false;
    }

    populateCalendar() {
        const firstDayOfMonth = this.getFirstDayOfMonth(this.dateValue);
        const daysInMonth = new Date(
            this.dateValue.getFullYear(),
            this.dateValue.getMonth() + 1,
            0
        ).getDate();
        const daysInPrevMonth = new Date(
            this.dateValue.getFullYear(),
            this.dateValue.getMonth(),
            0
        ).getDate();

        let day = 1;
        for (let i = 0; i < 5; i++) {
            this.calendar[i] = [];
            for (let j = 0; j < 7; j++) {
                if (i === 0 && j < firstDayOfMonth) {
                    this.calendar[i][j] = new SingleDay(
                        daysInPrevMonth - firstDayOfMonth + j + 1,
						this.currentMonth - 1,
						this.currentYear
					);
                } else if (day > daysInMonth) {
                    this.calendar[i][j] = new SingleDay(
                        day++ - daysInMonth,
						this.currentMonth + 1,
						this.currentYear
                    );
                } else {
                    this.calendar[i][j] = new SingleDay(
                        day++,
						this.currentMonth,
						this.currentYear
                    );
                }
            }
        }

        console.log(this.calendar);
    }

    openDatePicker() {
        this.showDatePicker = !this.showDatePicker;
    }

    formatDateToDDMMYYYY(date: Date) {
        // Get day, month, and year components
        const day = date.getDate();
        const month = date.getMonth() + 1; // Months are zero-based, so add 1
        const year = date.getFullYear();

        // Ensure two-digit format for day and month
        const formattedDay = day < 10 ? '0' + day : day;
        const formattedMonth = month < 10 ? '0' + month : month;

        // Combine components in "dd/mm/yyyy" format
        const formattedDate = `${formattedDay}/${formattedMonth}/${year}`;

        return formattedDate;
    }

    getFirstDayOfMonth(date: Date) {
        return new Date(date.getFullYear(), date.getMonth(), 1).getDay() - 1;
    }
}

class SingleDay {
    constructor(
        public value: number,
        public month: number,
        public year: number
    ) {}
}
<div
    ngClass="{{ showOuterDiv ? 'default-input' : '' }}"
    class="d-flex flex-wrap datepicker-wrapper"
>
    <label *ngIf="showLabel" for="date" class="default-label">{{
        labelString
    }}</label>

    <input
        type="text"
        [value]="
            dateValueString + (showTimePicker ? ' ' + timeValueString : '')
        "
        readonly
        (click)="openDatePicker()"
        class="no-style-input inner-input composed-input primary d-flex datepicker-input"
        placeholder="Select Date"
    />

    <div
        class="datepicker-container"
        ngClass="{{ showDatePicker ? 'active' : 'off' }}"
    >
        <div class="datepicker-navbar">
            <span class="datapicker-arrows" (click)="prevMonth()"> < </span>
            <span class="text-center">
                {{ monthsNames[currentMonth] }}
                {{ currentYear }}
                <!-- {{ monthNames[month] }} {{ year }} -->
            </span>
            <span class="datapicker-arrows" (click)="nextMonth()"> > </span>
        </div>
        <div class="datepicker-body">
            <div class="datepicker-row-weekdays">
                <div *ngFor="let day of weekDaysNames" class="datepicker-day">
                    {{ day }}
                </div>
            </div>
            <div *ngFor="let row of calendar" class="datepicker-row">
                <div
                    *ngFor="let day of row"
                    class="datepicker-day"
                    [ngClass]="{
						'other-month': !(day.month == currentMonth),
						'selected': dateValue.getDate() === day.value &&
							currentMonth === dateValue.getMonth() &&
							currentYear === dateValue.getFullYear()
                    }"
                    (click)="dayClick(day)"
                >
                    {{ day.value < 10 ? '&nbsp;' + day.value : day.value }}
                </div>
            </div>
        </div>
    </div>
</div>
